import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[
 dict(parent='13276',gloss=['all'],forms=['sūvā','savɔ','sūɛʔ','habe','sebe','sabāi','sep̚pāi','sabvi','hobai','hubai','sobai','sop','sabʰe','saib','sobu','sūb','sabhī','habbī','sɔbɔ'],citation='CDIAL[13276]',evidence='The full sarva entry gives Bashkarik sō/sūo, Lahnda/Pothwari habbā/habbh, Nepali/Bengali sab, Oriya sabo/sabu and Assamese sɔb/xɔb; it explicitly discusses irregular pronominal h/s and b developments. These whole all-forms fit that series, with final agreement/emphatic vowels retained. Multiword totality expressions and the unrelated-looking saf/bekti series are excluded.'),
 dict(parent='10896',gloss=['light'],forms=['halluŋ','hãlo','hallo','haluŋ','haluŋgo','halum','haruŋgo','haruŋga','haḷūā','hɔlū','halvi','alvā','alavā','alavā̃','olvo','ɔlvɔ','ollvo'],citation='CDIAL[10896]',evidence='Turner explicitly derives the metathesized series from laghu and names Nepali halũ/halaũ/huluṅo, Hindi harū/haruā and Gujarati haḷvũ. These whole light adjectives match that l/h or lv series, including nasal and final agreement vowels; initial h loss remains a regional comparison. Forms with k belong to the separate kk extension and are not silently merged here.'),
 dict(parent='10896-5',gloss=['light'],languages=['awan','Goj'],forms=['lokkā','ḷokā','lokke','loko / lokī'],citation='CDIAL[10896,extension kk]',evidence='The explicit kk extension lists Lahnda lohkā, Awankari laùkā and Punjabi lauhkā for light/small. The survey lokkā/lokā and Gujari masculine/feminine loko/lokī fit that contracted regional family, with source consonant quantity preserved. Both slash members share the same lexical parent.'),
 dict(parent='10951',gloss=['long'],languages=['Goj','kul','mewari_basad','AdivasiOriya'],forms=['lamõ / lamī','lamo / lambo','ˈloˈmmə','lomə','ˈlōmə','lommə','lumə','lɛmbo','lɔm'],citation='CDIAL[10951]',evidence='Turner lists Punjabi/Lahnda lammā/lambā, West Pahari lammo/lammā, Gujarati lā̃bũ and Oriya lambā; the addendum explicitly gives West Koci lɔmbo. These whole long adjectives fit that nasal or nasal-stop family and its ordinary agreement forms. The Kullu length noun lambāi and extended -la/-ḍa forms are excluded.'),
 dict(parent='10951',gloss=['long'],languages=['RathwiBareli','Bhilali','Rathawi','PauriBareli','Noiri','DungraBhili'],forms=['nambo','nāmbe','nāmbo','nāmbɔ','nāmbu','nāmbū','nāmbi','ṇāmbo'],citation='CDIAL[10951]',evidence='Turner’s lamba family combines the regional lamb-/lām- long series with Maithili namā, documenting an n-initial variant within the family. The western nāmb-/ṇāmb- survey adjectives preserve the matching medial mb and ordinary final agreement. This is a qualified comparative-family assignment: the local n/l alternation is not presented as a fully established regular sound law, and further -la extensions remain excluded.'),
 dict(parent='5260',gloss=['old'],languages=['Bhili','Noiri'],forms=['zūnū','dzūnū','dzunu','dzuna'],citation='CDIAL[5260]',evidence='Turner gives Prakrit juṇṇa, Gujarati jūnũ and Marathi junā under jūrṇa old. These unextended western zūn-/dzun- survey forms match that regional palatal/affricate series and agreement vowels. The short-i jīrṇa branch and l/ḍl-extended responses are not conflated with it.'),
 dict(parent='6767',gloss=['white'],languages=['Hajong','Bishnupriya','Bhili','kaithal'],forms=['dola','doḷo','doḷā'],citation='CDIAL[6767]',evidence='Turner explicitly lists Assamese/Bengali dhala/dhalā, Punjabi dhaulā and Gujarati dhɔḷũ white under dhavala. These survey dola/doḷo/doḷā forms fit that contracted l-bearing white family, preserving absent aspiration in the source. Forms without l/r require comparison with the separate dhava stem and are excluded.'),
]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):a.append(dict(record=r,parent=g['parent'],kind='reflex',citation=g['citation'],evidence=g['evidence'],family=i))
assert len(a)==len({x['record']['ID'] for x in a})
(P/'pass024-decisions.json').write_text(json.dumps(dict(accepted=a,held=[]),ensure_ascii=False,indent=1)+'\n')
(P/'pass024-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),[(g['parent'],sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
